@startuml

class OOBank {}

class OrganizationalUnit {}

class Division extends OrganizationalUnit {}

class Subdivision extends OrganizationalUnit {}

class Branch extends Subdivision {
  + address
  + number
}

class AccountType {
  + interestRate
  + monthlyFee
  + privileges
}

class Account {
  + number
  + balance
  + creditOrOverdraftLimit
}

class MortgageAccount extends Account {
  + collateralProperty
}

class CheckingAccount extends Account {}

class CreditCardAccount extends Account {
  + expiryDate
}

class CreditCard extends Account {}

class Customer {}

class Employee {}

OOBank "1" -- "*" Division
Division "1" -- "*" Subdivision
Subdivision "1" -- "*" Branch
Branch "1" -- "*" Account
Branch "1" -- "*" AccountType
Branch "1" -- "*" Customer
AccountType "1" -- "*" Account
Customer "1..2" -- "*" Account
Employee "0..1" -- "*" Customer : personal banker
Division "1" -- "1" Employee : manager
Division "1" -- "*" Employee : employees

@enduml

